// `require()` of builtins from bundled CommonJS gets the module itself (not an ESM namespace)
const EventEmitter = require("events");
const assert = require("node:assert");

// A guarded `require()` of a builtin that the runtime may not provide only fails when called
try {
  require("node:sea");
} catch {}

class Emitter extends EventEmitter {}

module.exports = new Emitter() instanceof EventEmitter && typeof assert === "function" ? "ok" : "fail";
